def process(load_data_corrected) -> pd.DataFrame:
    df = load_data_corrected.copy()

    # Parse date column
    df['Date'] = pd.to_datetime(df['Date'], format='%B %d, %Y', errors='coerce')

    # Extract year
    df['Year'] = df['Date'].dt.year

    # Handle Enterococcus values - convert to numeric, treating '<' prefixed values
    # The Tag columns contain '<' which means "less than", the actual value is in Enterococcus
    def parse_enterococcus(val):
        if pd.isna(val):
            return pd.NA
        try:
            return float(val)
        except:
            return pd.NA

    df['North_Enterococcus'] = df['Enterococcus'].apply(parse_enterococcus)
    df['Middle_Enterococcus'] = df['Enterococcus.1'].apply(parse_enterococcus)
    df['South_Enterococcus'] = df['Enterococcus.2'].apply(parse_enterococcus)

    # Keep only needed columns
    return df[['Date', 'Year', 'North_Enterococcus', 'Middle_Enterococcus', 'South_Enterococcus']]

def process(parse_data) -> pd.DataFrame:
    df = parse_data.copy()

    def parse_enterococcus(val):
        if pd.isna(val):
            return None
        val = str(val).strip()
        if val == '<' or val == '':
            return None
        try:
            return float(val)
        except:
            return None

    df['North_Value'] = df['North_Enterococcus'].apply(parse_enterococcus)
    df['Middle_Value'] = df['Middle_Enterococcus'].apply(parse_enterococcus)
    df['South_Value'] = df['South_Enterococcus'].apply(parse_enterococcus)

    return df[['Date', 'Year', 'North_Value', 'Middle_Value', 'South_Value']]
